<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/customer-auth.php';require_once dirname(__DIR__).'/collab/core.php';require_once dirname(__DIR__).'/collab/documents.php';require_once dirname(__DIR__).'/collab/files.php';require_once dirname(__DIR__).'/ai/routes.php';require_once dirname(__DIR__).'/pricing/routes.php';require_once __DIR__.'/templates.php';require_once __DIR__.'/schedule.php';
function lc_json(mixed $v):string{return json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);}
function lc_inn_valid(string $inn):bool{
 if(!preg_match('/^(?:[0-9]{10}|[0-9]{12})$/D',$inn)||preg_match('/^0+$/D',$inn))return false;
 $check=static function(array $weights,string $value):int{$sum=0;foreach($weights as $i=>$w)$sum+=$w*(int)$value[$i];return $sum%11%10;};
 return strlen($inn)===10?$check([2,4,10,3,5,9,4,6,8],$inn)===(int)$inn[9]:$check([7,2,4,10,3,5,9,4,6,8],$inn)===(int)$inn[10]&&$check([3,7,2,4,10,3,5,9,4,6,8],$inn)===(int)$inn[11];
}
function lc_ready():bool{return crm_query("SELECT state FROM nd_schema_migrations WHERE version='014_lifecycle_documents'")->fetchColumn()==='applied';}
function lc_gate():void{if(!lc_ready())crm_fail(503,'Документы ещё не подготовлены.');}
function lc_audit(array $a,string $entity,int $id,string $action,?int $version,array $evidence):void{crm_query('INSERT INTO nd_lc_audit(actor_type,actor_id,entity,record_id,action,prior_version,evidence_json) VALUES (?,?,?,?,?,?,?)',[$a['type'],$a['id'],$entity,$id,$action,$version,lc_json($evidence)]);}
function lc_template(int $id,bool $lock=false):array{$r=crm_query('SELECT * FROM nd_lc_templates WHERE id=?'.($lock?' FOR UPDATE':''),[$id])->fetch();if(!$r)crm_fail(404,'Шаблон не найден.');$r['clauses']=json_decode($r['clauses_json'],true,512,JSON_THROW_ON_ERROR);unset($r['clauses_json']);return $r;}
function lc_clauses(array $d):array{$c=$d['clauses']??null;if(!is_array($c)||array_keys($c)!==array_keys(lc_sections()))crm_fail(422,'Нужны все разделы шаблона в установленном порядке.');$allowed=[...array_keys(lc_input_labels()),'price','bank_details'];foreach($c as $k=>$text){$c[$k]=cc_text($c,$k,8000);preg_match_all('/\{\{([^{}]+)\}\}/',$text,$m);foreach($m[1] as $field)if(!in_array($field,$allowed,true))crm_fail(422,'Неизвестное поле шаблона.');if(str_contains(preg_replace('/\{\{[^{}]+\}\}/','',$text),'{{')||str_contains($text,'<?'))crm_fail(422,'Шаблон допускает только текст и известные поля.');}return $c;}
function lc_template_create(array $a,array $d):array{cc_owner($a);$kind=$d['kind']??'';if(!isset(lc_kinds()[$kind]))crm_fail(422,'Выберите тип документа.');$clauses=lc_clauses($d);$n=(int)crm_query('SELECT COALESCE(MAX(revision_number),0) FROM nd_lc_templates WHERE kind=?',[$kind])->fetchColumn()+1;$title=cc_text($d,'title',190);$hash=hash('sha256',lc_json([$kind,$title,$clauses]));crm_query('INSERT INTO nd_lc_templates(kind,revision_number,title,clauses_json,checksum) VALUES (?,?,?,?,?)',[$kind,$n,$title,lc_json($clauses),$hash]);$id=(int)db()->lastInsertId();lc_audit($a,'template',$id,'created',null,['hash'=>$hash]);return ['ok'=>true,'id'=>$id,'record'=>lc_template($id)];}
function lc_template_action(array $a,int $id,string $action,array $d):array{cc_owner($a);$t=lc_template($id,true);crm_version($d,$t);if(($d['checksum']??'')!==$t['checksum'])crm_fail(409,'Редакция шаблона изменилась.');$target=match($action){'review'=>'NEEDS_LEGAL_REVIEW','approve'=>'APPROVED','retire'=>'RETIRED',default=>''};$allowed=['review'=>['DRAFT'],'approve'=>['NEEDS_LEGAL_REVIEW'],'retire'=>['APPROVED']];if(!in_array($t['state'],$allowed[$action]??[],true)||($d['confirm']??false)!==true)crm_fail(409,'Проверьте состояние и подтвердите решение.');$reason=cc_text($d,'reason',2000);crm_query('UPDATE nd_lc_templates SET state=?,version=version+1,approval_reason=?,approved_by=?,approved_at=? WHERE id=?',[$target,$reason,$target==='APPROVED'?1:$t['approved_by'],$target==='APPROVED'?gmdate('Y-m-d H:i:s'):$t['approved_at'],$id]);lc_audit($a,'template',$id,$target,(int)$t['version'],['hash'=>$t['checksum'],'reason'=>$reason]);return ['ok'=>true,'id'=>$id,'record'=>lc_template($id)];}
function lc_binding(array $a,int $id,bool $lock=false):array{$r=crm_query('SELECT b.*,d.project_id,t.kind,t.title AS template_title FROM nd_lc_document_bindings b JOIN nd_cc_revisions v ON v.id=b.revision_id JOIN nd_cc_documents d ON d.id=v.document_id JOIN nd_lc_templates t ON t.id=b.template_id WHERE b.id=?'.($lock?' FOR UPDATE':''),[$id])->fetch();if(!$r)crm_fail(404,'Документ не найден.');cc_project($a,(int)$r['project_id']);if($a['type']==='customer'&&$r['state']==='OWNER_REVIEW')crm_fail(404,'Документ не найден.');return $r;}
function lc_generate(array $a,array $d):array{
 cc_owner($a);$t=lc_template(cc_id($d['template_id']??null),true);if($t['state']!=='APPROVED')crm_fail(409,'Нужна одобренная владельцем версия шаблона.');
 $p=cc_project($a,cc_id($d['project_id']??null),true,true);if(!$p['order_id'])crm_fail(422,'Свяжите проект с существующим заказом.');$order=crm_record('orders',(int)$p['order_id'],true);
 $q=pricing_detail(cc_id($d['quotation_id']??null));if((int)$q['project_id']!==(int)$p['id']||$q['state']!=='APPROVED'||!pricing_fresh($q))crm_fail(409,'Нужен актуальный одобренный расчёт этого проекта.');
 $in=$d['fields']??null;if(!is_array($in)||array_diff(array_keys($in),array_keys(lc_input_labels())))crm_fail(422,'Проверьте структурированные поля.');$fields=[];foreach(lc_input_labels() as $key=>$label)$fields[$key]=cc_text($in,$key,6000,$key!=='client_inn');
 foreach($fields as $value)if(preg_match('/-----BEGIN [A-Z ]*PRIVATE KEY|github_pat_|ghp_[A-Za-z0-9]{20}|sk-[A-Za-z0-9]{20}|(?:password|token|secret)\s*[=:]\s*\S+/i',$value))crm_fail(422,'Не включайте пароли, ключи и токены в документы.');
 if(strlen($fields['owner_inn'])!==12||!lc_inn_valid($fields['owner_inn'])||!in_array($fields['client_type'],['person','ip','company'],true))crm_fail(422,'Проверьте ИНН исполнителя и тип заказчика.');
 if($fields['client_type']!=='person'&&(!lc_inn_valid($fields['client_inn'])||strlen($fields['client_inn'])!==($fields['client_type']==='company'?10:12)))crm_fail(422,'Для ИП/организации нужны ИНН и полномочия.');
 if(!preg_match('/^[0-9]{20}$/D',$fields['bank_account'])||!preg_match('/^[0-9]{9}$/D',$fields['bank_bik'])||!preg_match('/^[0-9]{20}$/D',$fields['bank_corr']))crm_fail(422,'Проверьте длину банковских реквизитов.');
 $fields['bank_details']=$fields['owner_name'].'; '.$fields['bank_name'].'; счёт '.$fields['bank_account'].'; БИК '.$fields['bank_bik'].'; к/с '.$fields['bank_corr'];
 if(($d['owner_reviewed']??false)!==true)crm_fail(422,'Подтвердите проверку реквизитов, применимости НПД и всех условий.');
 $minor=(int)$q['calculation']['selling_minor'];$fields['price']=intdiv($minor,100).'.'.str_pad((string)($minor%100),2,'0',STR_PAD_LEFT);
 if(bill_minor($order['total_amount'])!==$minor)crm_fail(409,'Сумма черновика заказа должна совпадать с одобренной ценой.');
 $schedule=lc_schedule_parse($fields['payment_schedule'],$minor,(int)$p['id']);$fields['payment_schedule']=implode("\n",array_map(fn($r)=>$r['label'].': '.bill_decimal($r['amount_minor']).' RUB, до '.$r['due_on'].', условие '.$r['gate'].($r['stage_id']?' №'.$r['stage_id']:''),$schedule));
 $parts=[];foreach($t['clauses'] as $key=>$text){$rendered=preg_replace_callback('/\{\{([^{}]+)\}\}/',fn($m)=>$fields[$m[1]],$text);$parts[]=lc_sections()[$key]."\n".$rendered;}
 $number='ND-'.$order['id'].'-'.strtoupper(bin2hex(random_bytes(6)));$snapshot=['number'=>$number,'date'=>gmdate('Y-m-d'),'order_id'=>(int)$order['id'],'project_id'=>(int)$p['id'],'quotation'=>['id'=>(int)$q['id'],'checksum'=>$q['checksum']],'fields'=>$fields,'payment_schedule'=>$schedule];$template=['id'=>(int)$t['id'],'kind'=>$t['kind'],'revision_number'=>(int)$t['revision_number'],'checksum'=>$t['checksum'],'clauses'=>$t['clauses'],'approved_at'=>$t['approved_at']];$snapshot['rendered']=['title'=>$t['title'].' №'.$number,'description'=>implode("\n\n",$parts),'project_title'=>$p['title'],'customer_name'=>$fields['client_name']];$hash=hash('sha256',lc_json([$template,$snapshot]));
 $body=['title'=>$t['title'].' №'.$number,'description'=>implode("\n\n",$parts),'project_title'=>$p['title'],'customer_name'=>$fields['client_name'],'comments'=>'Дата '.$snapshot['date'].'. Заказ №'.$order['id'].'. Шаблон v'.$t['revision_number'].'. SHA-256 '.$hash.'. Подписание: копии с проверкой. Не чек НПД.'];
 crm_query("INSERT INTO nd_cc_documents(project_id,kind,title) VALUES (?,'description',?)",[$p['id'],$body['title']]);$doc=(int)db()->lastInsertId();crm_query("INSERT INTO nd_cc_revisions(document_id,revision_number,body,checksum,status) VALUES (?,1,?,?,'ready')",[$doc,lc_json($body),$hash]);$revision=(int)db()->lastInsertId();
 crm_query('INSERT INTO nd_lc_document_bindings(order_id,revision_id,template_id,template_snapshot,input_snapshot,generated_hash) VALUES (?,?,?,?,?,?)',[$order['id'],$revision,$t['id'],lc_json($template),lc_json($snapshot),$hash]);$id=(int)db()->lastInsertId();lc_audit($a,'document',$id,'generated',null,['hash'=>$hash,'template_id'=>$t['id'],'quotation_id'=>$q['id']]);cc_event($a,(int)$p['id'],'legal_document_drafted');return ['ok'=>true,'id'=>$id,'record'=>lc_binding($a,$id)];
}
function lc_document_action(array $a,int $id,string $action,array $d):array{
 $b=lc_binding($a,$id,true);cc_revision($a,(int)$b['revision_id']);cc_project($a,(int)$b['project_id'],true,true);crm_version($d,$b);if(($d['checksum']??'')!==$b['generated_hash'])crm_fail(409,'Контрольная сумма не совпадает.');$target='';$reason=cc_text($d,'reason',3000);$file=null;
 if($action==='send'){cc_owner($a);if($b['state']!=='OWNER_REVIEW'||($d['confirm']??false)!==true)crm_fail(409,'Подтвердите отправку проверенного документа.');if(lc_template((int)$b['template_id'])['state']!=='APPROVED')crm_fail(409,'Версия шаблона выведена из применения. Подготовьте документ по действующей версии.');if(!ca_enabled())crm_fail(503,'Отправка закрыта до одобрения политики кабинета и настройки клиентского доступа.');$target='SENT';crm_query("UPDATE nd_cc_revisions SET status='sent',sent_at=UTC_TIMESTAMP(),version=version+1 WHERE id=?",[$b['revision_id']]);}
 elseif($action==='response'){if($a['type']!=='customer'||!in_array($b['state'],['SENT','CLIENT_RESPONSE'],true))crm_fail(409,'Ответ сейчас недоступен.');$target='CLIENT_RESPONSE';}
 elseif($action==='signed-copy'){if(!in_array($b['state'],['SENT','CLIENT_RESPONSE','SIGNED_COPY_SUBMITTED'],true))crm_fail(409,'Документ не ожидает подписанную копию.');$files=cc_files_for($a,(int)$b['project_id'],[cc_id($d['file_id']??null)],true);$file=(int)$files[0]['id'];$target='SIGNED_COPY_SUBMITTED';}
 elseif($action==='verify'){cc_owner($a);if($b['state']!=='SIGNED_COPY_SUBMITTED'||!$b['signed_file_id']||($d['confirm']??false)!==true)crm_fail(409,'Сначала приложите подписанную копию и проверьте её.');$verifiedFile=cc_file($a,(int)$b['signed_file_id'],true);cc_file_path($verifiedFile);$target='AGREED';crm_query('UPDATE nd_lc_document_bindings SET verification_reason=?,verified_by=1,verified_at=UTC_TIMESTAMP() WHERE id=?',[$reason,$id]);}
 elseif($action==='reject'){cc_owner($a);if($b['state']==='AGREED'||($d['confirm']??false)!==true)crm_fail(409,'Согласованная версия сохраняется; изменение оформляется отдельно.');$target='REJECTED';}else crm_fail(404,'Действие не найдено.');
 crm_query('UPDATE nd_lc_document_bindings SET state=?,response=?,signed_file_id=COALESCE(?,signed_file_id),version=version+1 WHERE id=?',[$target,$reason,$file,$id]);lc_audit($a,'document',$id,$target,(int)$b['version'],['hash'=>$b['generated_hash'],'reason'=>$reason,'file_id'=>$file,'file_checksum'=>$file?cc_file($a,$file)['checksum']:($verifiedFile['checksum']??null)]);cc_event($a,(int)$b['project_id'],'legal_document_'.strtolower($target));return ['ok'=>true,'id'=>$id,'record'=>lc_binding($a,$id)];
}
